using System;
using NUnit.Framework;
namespace Wildfolk.Tests
{
    public sealed class PremiumAdmissionTests
    {
        private const string Host="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",Peer="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        private PremiumChallenge Challenge()=>new PremiumChallenge{HostPlayerId="host-account",SessionId=Guid.NewGuid().ToString("N"),AdmissionId=Guid.NewGuid().ToString("N"),Profile=Peer,OperationId=Guid.NewGuid().ToString("N")};
        private static PremiumAdmissionSnapshot Snapshot(PremiumChallenge c,string player="peer-account")=>new PremiumAdmissionSnapshot{ProofId=new string('a',64),PlayerId=player,HostPlayerId=c.HostPlayerId,SessionId=c.SessionId,AdmissionId=c.AdmissionId,Profile=c.Profile,OperationId=c.OperationId,SelectedClassId="engineer",AllowedClassIds=new[]{"engineer"},AccountRevision=1,EconomyRevision=2,IssuedAt="2026-10-27T00:00:00Z",ExpiresAt="2026-10-27T00:01:30Z"};
        private ClassAdmissionLocks Locks(){var locks=new ClassAdmissionLocks();Assert.That(locks.Admit(Host,new ClassAdmission{Profile=Peer,Selected="engineer",Owned=true,XP=999999,Nodes=Array.Empty<string>()},false,new SurvivorClassAdmission(),out _),Is.True);return locks;}
        [Test]public void BackendSnapshotAdmitsEngineerWithoutTrustingPeerXPOrNodes(){var locks=Locks();var c=Challenge();Assert.That(locks.CompletePremium(Peer,c,Snapshot(c),"peer-account"),Is.True);Assert.That(locks.TryGet(Peer,out var p),Is.True);Assert.That(p.Account.Selected,Is.EqualTo("engineer"));Assert.That(p.Persistent,Is.False);Assert.That(p.Account.Find("engineer").XP,Is.Zero);Assert.That(p.Account.Find("engineer").Nodes,Is.Empty);}
        [Test]public void MissingProofLeavesSafeSurvivorAndNoOwnershipGrant(){var locks=Locks();Assert.That(locks.CompletePremium(Peer,Challenge(),null,"peer-account"),Is.False);locks.TryGet(Peer,out var p);Assert.That(p.Account.Selected,Is.EqualTo("survivor"));Assert.That(p.Account.Find("engineer").Owned,Is.False);}
        [TestCase("player")][TestCase("session")][TestCase("admission")][TestCase("profile")][TestCase("operation")][TestCase("class")][TestCase("expiry")][TestCase("proof")]
        public void CrossBindingOrMalformedSnapshotCannotMaterialize(string kind){var c=Challenge();var s=Snapshot(c);switch(kind){case "player":s.PlayerId="other";break;case "session":s.SessionId=Guid.NewGuid().ToString("N");break;case "admission":s.AdmissionId=Guid.NewGuid().ToString("N");break;case "profile":s.Profile=Host;break;case "operation":s.OperationId=Guid.NewGuid().ToString("N");break;case "class":s.SelectedClassId="not-a-class";break;case "expiry":s.ExpiresAt=s.IssuedAt;break;case "proof":s.ProofId="local-owned-flag";break;}Assert.That(Locks().CompletePremium(Peer,c,s,"peer-account"),Is.False);}
        [Test]public void SameSessionReconnectReverifiesAndKeepsOnlyItsEphemeralXP(){var locks=Locks();var c=Challenge();locks.CompletePremium(Peer,c,Snapshot(c),"peer-account");locks.TryGet(Peer,out var progress);Assert.That(progress.Grant(Peer,"engineer",8,"event"),Is.True);var reconnect=Challenge();reconnect.SessionId=c.SessionId;locks.CompletePremium(Peer,reconnect,Snapshot(reconnect),"peer-account");locks.TryGet(Peer,out var restored);Assert.That(restored,Is.SameAs(progress));Assert.That(restored.Account.Find("engineer").XP,Is.EqualTo(8));Assert.That(restored.Grant(Peer,"engineer",8,"event"),Is.False);locks.CompletePremium(Peer,Challenge(),null,"peer-account");locks.TryGet(Peer,out var fallback);Assert.That(fallback.Account.Selected,Is.EqualTo("survivor"));}
        [Test]public void DifferentAuthenticatedAccountCannotInheritRemoteClassXP(){var locks=Locks();var c=Challenge();locks.CompletePremium(Peer,c,Snapshot(c),"peer-account");locks.TryGet(Peer,out var old);old.Grant(Peer,"engineer",8,"event");c=Challenge();locks.CompletePremium(Peer,c,Snapshot(c,"other-account"),"other-account");locks.TryGet(Peer,out var next);Assert.That(next.Account.Find("engineer").XP,Is.Zero);}
        [Test]public void FreshHostHasNoPremiumTrustCacheAndGoldClaimsKeepTheirExistingPolicy(){var locks=Locks();var c=Challenge();locks.CompletePremium(Peer,c,Snapshot(c),"peer-account");locks.Clear();Assert.That(locks.TryGet(Peer,out _),Is.False);Assert.That(locks.Admit(Host,new ClassAdmission{Profile=Peer,Selected="warrior",Owned=true,XP=99999,Nodes=Array.Empty<string>()},false,new SurvivorClassAdmission(),out var p),Is.True);Assert.That(p.Account.Selected,Is.EqualTo("survivor"));Assert.That(p.Persistent,Is.False);}
    }
}
